window.PORTAL={"day": 6, "title": "Neonatal Jaundice", "docTitle": "DAY 6 — NEONATAL JAUNDICE", "subtitle": ["Phototherapy • Exchange Transfusion • Hemolytic Disease", "NEET-SS + ICP Paediatrics 2026 Master Course | Premium Core-Day Standard"], "source": "source/Day_6_NEET_SS_ICP_Paediatrics_2026_V3_7-13-27-20-8_RandomKey.docx", "pages": [{"id": "overview", "title": "Overview", "group": "Start", "kind": "overview", "sections": [{"title": "", "blocks": [{"t": "p", "html": "<strong>Phototherapy • Exchange Transfusion • Hemolytic Disease</strong>"}, {"t": "p", "html": "<strong>NEET-SS + ICP Paediatrics 2026 Master Course | Premium Core-Day Standard</strong>"}, {"t": "p", "html": "Schedule mapping: 03 Oct 2026 = Day 5 → 04 Oct 2026 = Day 6"}, {"t": "callout", "label": "SCHEDULE UNCHANGED — DAY 6 ONLY", "title": "", "html": ["No schedule is modified. This regeneration only upgrades Day 6: Neonatal Jaundice + Phototherapy + Exchange Transfusion + Hemolytic Disease, while preserving the previously locked Day 3/Day 5 swap."], "fill": "1F4E78"}, {"t": "callout", "label": "GUIDELINE CURRENCY", "title": "", "html": ["Primary treatment framework: AAP 2022 hyperbilirubinemia guideline for infants ≥35 weeks. Phototherapy delivery concepts cross-checked against the AAP 2024 phototherapy technical report. NICE CG98 is labelled separately when used for contrast/procedure-level teaching. Guidance is not blended when criteria differ."], "fill": "1F4E78"}]}, {"title": "4-Hour Session Objectives", "h1": "4-Hour Session Objectives", "blocks": [{"t": "list", "ordered": false, "items": ["Distinguish physiologic jaundice from pathologic hyperbilirubinemia using onset, trajectory and clinical context.", "Interpret TcB, TSB, direct bilirubin, rate of rise, DAT, CBC, reticulocytes, smear, G6PD and albumin.", "Apply gestational age, postnatal age in hours and neurotoxicity risk factors to AAP treatment decisions.", "Recognize Rh, ABO and minor-antigen HDFN, G6PD deficiency and hereditary spherocytosis.", "Prescribe effective intensive phototherapy and troubleshoot inadequate response.", "Recognize escalation-of-care before the exchange line is reached and sequence emergency actions.", "Use IVIG only in the correct guideline-defined setting and understand why it cannot delay exchange readiness.", "Recognize acute bilirubin encephalopathy and chronic kernicterus spectrum.", "Explain indications, principles, monitoring and complications of exchange transfusion.", "Solve NEET-SS/INI-CET-SS level clinical vignettes that require “what next?” reasoning."]}]}, {"title": "Objective Verification Map", "h1": "", "blocks": [{"t": "table", "head": ["<strong>Objective</strong>", "<strong>Skill</strong>", "<strong>Mapped case(s)</strong>", "<strong>Mapped MCQ(s)</strong>"], "rows": [["1", "Physiologic vs pathologic jaundice", "Case 1", "MCQ 1, 21, 43"], ["2", "Interpret bilirubin/hemolysis data", "Case 3 / 6", "MCQ 12, 31, 52"], ["3", "Apply GA + age-hours + risk factors", "Case 2", "MCQ 9, 22, 37, 50"], ["4", "Recognize immune/nonimmune hemolysis", "Case 4 / 5 / 6", "MCQ 30, 31, 38, 53"], ["5", "Prescribe/troubleshoot intensive phototherapy", "Case 7", "MCQ 17, 29, 61"], ["6", "Recognize escalation before exchange", "Case 8", "MCQ 3, 23, 48, 56"], ["7", "Use IVIG only in correct setting", "Case 8", "MCQ 15, 34, 47, 57"], ["8", "Recognize ABE/kernicterus", "Case 9", "MCQ 5, 24, 36, 62, 67"], ["9", "Apply exchange-transfusion principles", "Case 10", "MCQ 44, 49, 59, 75"], ["10", "Integrate feeding/cholestasis/genetics", "Case 1 / 5", "MCQ 18, 27, 28, 60, 64"]]}]}, {"title": "Four-Hour Study Plan", "h1": "Four-Hour Study Plan", "blocks": [{"t": "table", "head": ["<strong>Time</strong>", "<strong>Focus</strong>"], "rows": [["0:00–0:40", "Bilirubin physiology; unconjugated vs conjugated jaundice; physiologic/pathologic distinction"], ["0:40–1:20", "AAP ≥35-week decision framework; TcB/TSB; neurotoxicity risk; rate of rise"], ["1:20–2:05", "Hemolytic disease: Rh, ABO, Kell/minor antigens, G6PD, HS"], ["2:05–2:45", "Intensive phototherapy, response, stopping, rebound, failure analysis"], ["2:45–3:15", "Escalation, IVIG, ABE, exchange transfusion"], ["3:15–3:35", "Progressive cases + data interpretation"], ["3:35–4:00", "75 MCQs + targeted review"]]}]}]}, {"id": "part-1", "title": "Bilirubin Physiology & Clinical Classification", "eyebrow": "Part I", "group": "Study Notes", "kind": "notes", "sections": [{"title": "1. Bilirubin Metabolism", "blocks": [{"t": "grid", "items": [{"label": "WHAT", "html": "Heme → biliverdin → unconjugated bilirubin"}, {"label": "WHY", "html": "Newborns produce more bilirubin/kg and clear less"}, {"label": "HOW", "html": "Albumin transport → hepatic uptake → UGT1A1 conjugation → bile"}, {"label": "RECOGNIZE", "html": "Unconjugated bilirubin rises when production &gt; clearance"}, {"label": "WHAT NEXT", "html": "Identify production, conjugation, feeding/enterohepatic and illness contributors"}]}, {"t": "callout", "label": "CORE", "title": "", "html": ["Neonates have a relatively high RBC mass, shorter RBC lifespan, immature hepatic conjugation and enhanced enterohepatic circulation. Prematurity, bruising/cephalohematoma, hemolysis, poor intake and genetic disorders can push bilirubin upward."], "fill": "1F4E78"}, {"t": "callout", "label": "NEET-SS HIGH YIELD", "title": "", "html": ["Albumin-bound bilirubin is less able to enter the CNS. Albumin &lt;3.0 g/dL is an AAP bilirubin neurotoxicity risk factor. The clinical danger is influenced by more than the bilirubin number alone."], "fill": "7F6000"}, {"t": "callout", "label": "ADVANCED / RANK DIFFERENTIATING", "title": "", "html": ["The bilirubin/albumin ratio may support exchange decisions, but it is an adjunct—not a substitute for TSB thresholds or neurologic signs."], "fill": "843C0C"}]}, {"title": "2. Unconjugated vs Conjugated Hyperbilirubinemia", "blocks": [{"t": "table", "head": ["<strong>Feature</strong>", "<strong>Unconjugated</strong>", "<strong>Conjugated / direct</strong>"], "rows": [["Typical mechanism", "Overproduction; impaired uptake/conjugation; increased enterohepatic circulation", "Impaired bile formation/excretion or obstruction"], ["Urine bilirubin", "Absent", "May be present → dark urine"], ["Stool", "Usually pigmented", "Pale/acholic stool is a red flag"], ["Examples", "Physiologic, poor intake, HDFN, G6PD, HS, bruising, UGT defects", "Biliary atresia, neonatal hepatitis, infection, metabolic disease"], ["Phototherapy", "Useful when treatment threshold reached", "Does not treat underlying cholestasis"], ["Exam danger", "Bilirubin neurotoxicity", "Missing time-sensitive cholestasis"]]}, {"t": "callout", "label": "CRITICAL TRAP", "title": "", "html": ["Do NOT subtract direct bilirubin from TSB before applying AAP phototherapy/escalation/exchange thresholds. A very large direct fraction is a reason for expert assessment—not for an invented “corrected TSB.”"], "fill": "1F4E78"}]}, {"title": "3. Physiologic vs Pathologic Jaundice", "blocks": [{"t": "table", "head": ["<strong>Finding</strong>", "<strong>Interpretation</strong>"], "rows": [["Jaundice &lt;24 h", "Pathologic until evaluated"], ["Rapid bilirubin rise", "Suggests excessive production/hemolysis"], ["Anemia + reticulocytosis", "Hemolysis likely"], ["Poor feeding + excess weight loss + low stool output", "Suboptimal-intake hyperbilirubinemia"], ["Large bruise/cephalohematoma", "Extravascular heme load"], ["Dark urine + pale stool", "Conjugated hyperbilirubinemia/cholestasis"], ["Persistent jaundice", "Reassess feeding; direct bilirubin; thyroid/hemolysis/infection based on context"]]}]}, {"title": "Mechanistic Pathophysiology — WHAT -> WHY -> HOW", "blocks": [{"t": "p", "html": "CHAIN 1 — Neonatal bilirubin accumulation<br>High neonatal RBC mass + shorter RBC survival -&gt; increased heme turnover -&gt; increased unconjugated bilirubin production -&gt; immature hepatic uptake/UGT1A1 conjugation + increased enterohepatic circulation -&gt; TSB rises. WHY: production exceeds immature clearance.<br><br>CHAIN 2 — Hemolysis to bilirubin neurotoxicity<br>Immune/nonimmune RBC destruction -&gt; abrupt bilirubin production + anemia/reticulocytosis -&gt; albumin-binding reserve becomes stressed; low albumin, sepsis or clinical instability further lowers the safety margin -&gt; more unbound bilirubin reaches the brain -&gt; basal ganglia/brainstem injury -&gt; ABE -&gt; kernicterus if permanent.<br><br>CHAIN 3 — Poor feeding to rising bilirubin<br>Inadequate milk transfer -&gt; low intake + fewer stools -&gt; more intestinal bilirubin remains available for deconjugation -&gt; increased enterohepatic reabsorption -&gt; rising unconjugated TSB. WHY: feeding correction reduces a continuing bilirubin source but does not replace threshold-based treatment."}]}]}, {"id": "part-2", "title": "AAP ≥35-Week Decision Framework", "eyebrow": "Part II", "group": "Study Notes", "kind": "notes", "sections": [{"title": "4. Five Variables Before Any Decision", "blocks": [{"t": "list", "ordered": true, "items": ["Gestational age at birth.", "Postnatal age in HOURS.", "Total serum bilirubin (TSB).", "Presence/absence of bilirubin neurotoxicity risk factors.", "Trajectory + clinical context: rate of rise, feeding, illness, hemolysis and response to therapy."]}, {"t": "callout", "label": "AAP NEUROTOXICITY RISK FACTORS", "title": "", "html": ["Albumin &lt;3.0 g/dL; isoimmune hemolytic disease; G6PD deficiency or other hemolytic condition; sepsis; or significant clinical instability in the previous 24 hours."], "fill": "1F4E78"}, {"t": "callout", "label": "35–37 6/7 WEEK TRAP", "title": "", "html": ["Gestational age is already built into the treatment curves. Do not automatically use the “additional neurotoxicity risk factor” curve merely because an infant is 35–37 6/7 weeks. Another neurotoxicity risk factor must be present."], "fill": "1F4E78"}]}, {"title": "5. TcB vs TSB", "blocks": [{"t": "table", "head": ["<strong>Situation</strong>", "<strong>Action</strong>"], "rows": [["Routine screening", "TcB or TSB can screen according to setting"], ["TcB within 3 mg/dL of phototherapy threshold", "Obtain TSB"], ["TcB ≥15 mg/dL", "Obtain TSB"], ["Any phototherapy/escalation/exchange decision", "Use TSB"], ["Immediately after phototherapy", "Do not assume TcB is interchangeable with TSB; follow guideline timing"]]}]}, {"title": "6. Bilirubin Rate of Rise", "blocks": [{"t": "table", "head": ["<strong>Age</strong>", "<strong>Rate that is exceptional and suggests hemolysis</strong>"], "rows": [["First 24 h", "≥0.3 mg/dL/hour"], ["After 24 h", "≥0.2 mg/dL/hour"]]}, {"t": "callout", "label": "WHAT WOULD YOU DO NEXT?", "title": "", "html": ["If the rate suggests hemolysis: confirm/track TSB, review maternal/infant blood groups and maternal antibodies, obtain DAT when appropriate, CBC/Hb, reticulocyte count and smear, and consider G6PD/HS depending on the pattern. Do not delay indicated phototherapy while completing the cause work-up."], "fill": "1F4E78"}]}]}, {"id": "part-3", "title": "Hemolytic Disease & High-Production States", "eyebrow": "Part III", "group": "Study Notes", "kind": "notes", "sections": [{"title": "7. Rh Alloimmune HDFN", "blocks": [{"t": "grid", "items": [{"label": "WHAT", "html": "Maternal IgG targets fetal RBC antigen"}, {"label": "WHY", "html": "Placental IgG causes fetal/neonatal RBC destruction"}, {"label": "HOW", "html": "Hemolysis → anemia ± hydrops; bilirubin rises after birth"}, {"label": "RECOGNIZE", "html": "Maternal antibody history, DAT, anemia, reticulocytosis"}, {"label": "WHAT NEXT", "html": "Treat bilirubin by severity and anticipate anemia/late anemia"}]}, {"t": "callout", "label": "HIGH YIELD", "title": "", "html": ["Rh disease may be severe enough to cause fetal anemia/hydrops. After birth, bilirubin and anemia need parallel attention. Anti-D prophylaxis prevents maternal sensitization in eligible RhD-negative pregnancies."], "fill": "1F4E78"}, {"t": "p", "html": "<strong>RhD PREVENTION &amp; ANTI-D DOSING — EXAM-SAFE NOTE<br></strong>Anti-D immunoglobulin prevents maternal RhD alloimmunization; it does not treat a woman who is already sensitized. A common FDA-labelled regimen is 300 µg (1500 IU) at 26–28 weeks and 300 µg (1500 IU) within 72 hours after delivery if the newborn is RhD-positive. For pregnancy loss/termination up to 12 weeks, a 50 µg (250 IU) preparation is labelled where available; 300 µg can be used if the smaller preparation is unavailable. After delivery, invasive procedures or other sensitizing events, quantify fetomaternal hemorrhage when indicated and give additional anti-D for larger fetal-RBC exposure (a 300-µg dose covers about 15 mL fetal RBCs in the FDA label). UK/NICE routine antenatal regimens are product-dependent and include a single 1500-IU dose at 28–30 weeks or two-dose regimens at 28 and 34 weeks; postpartum prophylaxis is still required after an RhD-positive birth. For exams, state the regimen/source when a question is guideline-specific."}]}, {"title": "8. ABO HDFN", "blocks": [{"t": "p", "html": "Most classic pattern: group O mother with group A or B infant. Maternal IgG anti-A/anti-B can cross the placenta. ABO HDFN can affect a first pregnancy. DAT may be positive, but DAT strength does not grade bilirubin severity."}, {"t": "callout", "label": "TRAP", "title": "", "html": ["A positive DAT supports immune sensitization; it does not independently mandate phototherapy, IVIG or exchange."], "fill": "1F4E78"}]}, {"title": "9. Minor Antigens — Kell, c, E and Others", "blocks": [{"t": "p", "html": "Clinically important maternal alloantibodies other than anti-D can cause HDFN. Anti-Kell is especially exam-worthy because anemia can be severe from both immune destruction and suppression of erythropoiesis; reticulocytosis may therefore be less dramatic than expected for the degree of anemia."}]}, {"title": "10. G6PD Deficiency", "blocks": [{"t": "table", "head": ["<strong>Feature</strong>", "<strong>Exam point</strong>"], "rows": [["DAT", "Negative"], ["Anemia", "May be mild despite severe bilirubin"], ["Trigger", "May be absent"], ["Acute assay trap", "Reticulocytosis/selective loss of deficient cells can give a falsely reassuring result"], ["Next step if suspicion persists", "Repeat enzyme testing later"], ["Clinical danger", "Hazardous hyperbilirubinemia/kernicterus"]]}]}, {"title": "11. Hereditary Spherocytosis (HS)", "blocks": [{"t": "table", "head": ["<strong>Clue</strong>", "<strong>Interpretation</strong>"], "rows": [["DAT", "Negative"], ["Spherocytes", "Supportive but not specific"], ["MCHC", "Often high"], ["Family history", "Jaundice, anemia, gallstones or splenectomy"], ["Neonatal phenotype", "Jaundice may dominate early"]]}, {"t": "callout", "label": "RANK DIFFERENTIATOR", "title": "", "html": ["DAT-positive + spherocytes → immune hemolysis remains very plausible. DAT-negative + high MCHC + spherocytes + family history → hereditary spherocytosis becomes much more likely."], "fill": "843C0C"}]}, {"title": "12. Hemolysis Work-Up", "blocks": [{"t": "table", "head": ["<strong>Test</strong>", "<strong>Purpose / interpretation</strong>"], "rows": [["Maternal + infant ABO/Rh", "Context for incompatibility"], ["Maternal antibody screen/history", "Identifies clinically important alloantibodies"], ["DAT", "Supports immune coating of RBCs"], ["CBC/Hb/Hct", "Quantifies anemia"], ["Reticulocytes", "Marrow response; may be atypical in Kell disease"], ["Peripheral smear", "Spherocytes/polychromasia/other morphology"], ["G6PD activity", "Enzyme deficiency; repeat if acute test is misleading"], ["MCHC / targeted HS testing", "Supports membrane disorder"], ["Albumin", "Neurotoxicity risk and exchange adjunct"], ["ETCOc if available", "Marker of heme catabolism/hemolysis"]]}]}]}, {"id": "part-4", "title": "Intensive Phototherapy", "eyebrow": "Part IV", "group": "Study Notes", "kind": "notes", "sections": [{"title": "13. Mechanism & Prescription", "blocks": [{"t": "grid", "items": [{"label": "WHAT", "html": "Blue-green photons act on bilirubin in skin"}, {"label": "WHY", "html": "Photoproducts can be excreted without normal hepatic conjugation"}, {"label": "HOW", "html": "Dose depends on wavelength, irradiance, distance and exposed area"}, {"label": "RECOGNIZE", "html": "TSB should fall; inadequate fall triggers troubleshooting"}, {"label": "WHAT NEXT", "html": "Verify delivery and assess ongoing production"}]}, {"t": "callout", "label": "AAP 2024 PHOTOTHERAPY TECHNICAL REPORT", "title": "", "html": ["Effective devices use blue-to-green light in the ~460–490 nm range and intensive phototherapy targets irradiance ≥30 µW/cm²/nm in term infants, applied over as much exposed body surface area as practical. Device-specific calibration and radiometry matter."], "fill": "1F4E78"}, {"t": "table", "head": ["<strong>Element</strong>", "<strong>High-quality intensive phototherapy</strong>"], "rows": [["Spectrum", "Blue-green ~460–490 nm"], ["Irradiance", "≥30 µW/cm²/nm in term infants"], ["Surface area", "Maximize exposed skin"], ["Distance", "Follow device instructions; excess distance lowers dose"], ["Interruptions", "Minimize during severe hyperbilirubinemia"], ["Monitoring", "Trend TSB and clinical status"]]}]}, {"title": "14. Why Phototherapy Fails", "blocks": [{"t": "table", "head": ["<strong>Cause</strong>", "<strong>Clue</strong>", "<strong>Next step</strong>"], "rows": [["Low irradiance / wrong distance", "Measured dose low", "Correct setup; remeasure irradiance"], ["Too little skin exposed", "Diaper/blanket/positioning", "Increase exposed area"], ["Brisk hemolysis", "Anemia/retic/rapid rise", "Hemolysis work-up + escalation assessment"], ["Wrong curve", "GA/risk-factor mistake", "Recalculate correctly"], ["Using TcB for treatment decision", "Discordant estimate", "Obtain TSB"], ["Conjugated disease", "Dark urine/pale stool/direct bilirubin", "Cholestasis pathway"], ["Unexpected lab mismatch", "Clinical discordance", "Repeat TSB promptly"]]}, {"t": "callout", "label": "EXAM PEARL", "title": "", "html": ["“Double phototherapy” is a device arrangement, not proof that the infant is receiving an intensive phototherapy dose. The measurable dose is what matters."], "fill": "1F4E78"}]}, {"title": "15. Stopping Phototherapy & Rebound", "blocks": [{"t": "callout", "label": "AAP STOPPING OPTION", "title": "", "html": ["Phototherapy may be stopped when TSB is at least 2 mg/dL below the hour-specific threshold at which phototherapy was started. Longer treatment is reasonable when rebound risk is high."], "fill": "1F4E78"}, {"t": "callout", "label": "HIGH REBOUND RISK", "title": "", "html": ["GA &lt;38 weeks; phototherapy started &lt;48 hours; hemolytic disease; and TSB close to the phototherapy threshold when treatment is stopped. Follow-up timing should be individualized to rebound risk."], "fill": "1F4E78"}]}]}, {"id": "part-5", "title": "Escalation, IVIG, ABE & Exchange", "eyebrow": "Part V", "group": "Study Notes", "kind": "notes", "sections": [{"title": "16. Escalation-of-Care", "blocks": [{"t": "callout", "label": "MUST-KNOW NUMBER", "title": "", "html": ["AAP escalation-of-care threshold = 2 mg/dL BELOW the exchange transfusion threshold."], "fill": "1F4E78"}, {"t": "table", "head": ["<strong>Immediate action</strong>", "<strong>Reason</strong>"], "rows": [["Intensive phototherapy", "Maximize bilirubin elimination"], ["IV hydration", "Support emergency treatment pathway"], ["NICU/neonatologist + transfer if exchange unavailable", "Exchange capability must be ready"], ["STAT TSB/direct bilirubin, CBC, albumin, chemistries, type &amp; crossmatch", "Clarify severity and prepare exchange"], ["TSB at least every 2 h", "Track emergency trajectory"], ["Continue cause assessment", "Hemolysis influences trajectory/adjuncts"], ["Prepare exchange without interrupting light", "Avoid delay"]]}]}, {"title": "17. IVIG — Keep Guidelines Separate", "blocks": [{"t": "table", "head": ["<strong>Framework</strong>", "<strong>Criterion / dose</strong>"], "rows": [["AAP 2022", "DAT-positive isoimmune hemolytic disease when TSB reaches/exceeds escalation threshold: IVIG 0.5–1 g/kg over 2 h may be considered; may repeat in 12 h. Benefit uncertain and exchange readiness continues."], ["NICE CG98", "Rh or ABO hemolytic disease with bilirubin continuing to rise &gt;8.5 µmol/L/h (~0.5 mg/dL/h) despite continuous intensified phototherapy: IVIG 500 mg/kg over 4 h."]]}, {"t": "callout", "label": "WHY THIS MATTERS", "title": "", "html": ["A common exam error is to blend the AAP and NICE IVIG criteria into one nonexistent rule. If a stem names the guideline, use that guideline’s criterion."], "fill": "1F4E78"}]}, {"title": "18. Acute Bilirubin Encephalopathy", "blocks": [{"t": "table", "head": ["<strong>Stage</strong>", "<strong>Findings</strong>", "<strong>Implication</strong>"], "rows": [["Early", "Lethargy, hypotonia, poor suck", "Urgent aggressive treatment; potentially reversible"], ["Intermediate", "Irritability, hypertonia, high-pitched cry, retrocollis/opisthotonos", "Urgent exchange"], ["Advanced", "Pronounced arching, apnea, seizures/coma", "Emergency exchange + intensive support"], ["Chronic kernicterus spectrum", "Dystonia/choreoathetosis, auditory neuropathy, gaze abnormality, enamel dysplasia", "Permanent sequelae"]]}, {"t": "callout", "label": "CRITICAL TRAP", "title": "", "html": ["Intermediate/advanced ABE is an urgent exchange indication even when the current TSB is slightly below the numeric exchange threshold or is falling."], "fill": "1F4E78"}]}, {"title": "19. Exchange Transfusion", "blocks": [{"t": "callout", "label": "INDICATIONS", "title": "", "html": ["Urgent exchange when TSB is at/above the exchange threshold OR when intermediate/advanced ABE is present."], "fill": "1F4E78"}, {"t": "callout", "label": "DOUBLE-VOLUME CONCEPT", "title": "", "html": ["A double-volume exchange replaces roughly two circulating blood volumes. Exact volume, aliquot size, product specification and access technique must follow NICU/transfusion-medicine protocols. The procedure removes bilirubin and antibody-coated RBCs while replacing susceptible cells with compatible donor RBCs."], "fill": "1F4E78"}, {"t": "list", "ordered": true, "items": ["Continue intensive phototherapy during preparation and whenever feasible during the exchange.", "Coordinate blood-bank selection based on maternal antibody and infant compatibility.", "Use continuous cardiorespiratory and temperature monitoring.", "Monitor glucose, electrolytes/calcium as clinically indicated, hematology and hemodynamics.", "After exchange, continue intensive phototherapy and recheck bilirubin promptly; monitor rebound and ongoing hemolysis/late anemia."]}]}, {"title": "20. Exchange Complications", "blocks": [{"t": "table", "head": ["<strong>Category</strong>", "<strong>Examples</strong>"], "rows": [["Cardiovascular", "Bradycardia, arrhythmia, BP/volume instability"], ["Metabolic", "Glucose disturbance, hypocalcemia, K+ and acid-base abnormalities"], ["Hematologic", "Thrombocytopenia, coagulopathy, rebound hemolysis"], ["Vascular", "Catheter injury, thrombosis, portal complications"], ["GI", "NEC risk"], ["Temperature", "Hypothermia"], ["Transfusion-related", "Compatibility/infectious risks mitigated by appropriate component selection"]]}]}]}, {"id": "part-6", "title": "Special High-Yield Topics", "eyebrow": "Part VI", "group": "Study Notes", "kind": "notes", "sections": [{"title": "21. Suboptimal-Intake Hyperbilirubinemia", "blocks": [{"t": "p", "html": "Think poor transfer, excessive weight loss, infrequent urine/stool output and increased enterohepatic circulation. Treat bilirubin by threshold AND fix feeding with observed feeding/latch assessment, lactation support and supplementation when clinically indicated."}]}, {"title": "22. Breast-Milk Jaundice", "blocks": [{"t": "p", "html": "Typically later and associated with a thriving breastfed infant after dangerous causes have been excluded. The label does not replace bilirubin severity assessment."}]}, {"title": "23. Cholestasis / Prolonged Jaundice", "blocks": [{"t": "p", "html": "Direct/conjugated hyperbilirubinemia is pathologic. Pale stools and dark urine require urgent cholestasis evaluation. Phototherapy does not treat biliary obstruction or hepatocellular cholestasis."}]}, {"title": "24. Crigler-Najjar vs Gilbert Syndrome", "blocks": [{"t": "table", "head": ["<strong>Feature</strong>", "<strong>CN Type I</strong>", "<strong>CN Type II</strong>", "<strong>Gilbert</strong>"], "rows": [["UGT1A1", "Absent/near absent", "Reduced", "Mildly reduced"], ["Severity", "Severe neonatal unconjugated hyperbilirubinemia", "Moderate", "Mild intermittent"], ["Phenobarbital response", "Absent", "Present", "Can reduce bilirubin but rarely needed"], ["Kernicterus risk", "Very high untreated", "Possible", "Not typical"]]}]}]}, {"id": "numbers", "title": "Must-Know Numbers", "group": "Quick Reference", "kind": "notes", "sections": [{"title": "", "blocks": [{"t": "table", "head": ["<strong>Number / rule</strong>", "<strong>Meaning</strong>"], "rows": [["≥35 weeks", "AAP 2022 treatment graphs apply"], ["TcB within 3 mg/dL of threshold", "Obtain TSB"], ["TcB ≥15 mg/dL", "Obtain TSB"], ["≥0.3 mg/dL/h &lt;24 h", "Suggests hemolysis"], ["≥0.2 mg/dL/h ≥24 h", "Suggests hemolysis"], ["Albumin &lt;3.0 g/dL", "Neurotoxicity risk factor"], ["~460–490 nm", "Effective phototherapy spectrum"], ["≥30 µW/cm²/nm", "Intensive phototherapy target in term infants"], ["2 mg/dL below exchange line", "Escalation threshold"], ["TSB at least q2h", "During escalation"], ["IVIG 0.5–1 g/kg over 2 h", "AAP option for appropriate DAT-positive isoimmune disease at escalation threshold"], ["Repeat IVIG in 12 h", "AAP permits a repeat if used"], ["≥2 mg/dL below starting threshold", "AAP stopping option for phototherapy; individualize rebound risk"], ["2 × 85 mL/kg = 170 mL/kg", "Exam approximation for a term double-volume exchange when circulating blood volume is taken as ~85 mL/kg. Use the NICU/blood-bank protocol for the exact calculated exchange volume."]]}]}]}, {"id": "tables", "title": "Tables & Algorithms", "group": "Quick Reference", "kind": "notes", "sections": [{"title": "Part VIII — Comparison Tables", "h1": "Part VIII — Comparison Tables", "blocks": [{"t": "table", "head": ["<strong>Feature</strong>", "<strong>Rh HDFN</strong>", "<strong>ABO HDFN</strong>", "<strong>G6PD</strong>", "<strong>HS</strong>"], "rows": [["DAT", "Usually +", "Often +", "−", "−"], ["First pregnancy", "Less typical for anti-D sensitization", "Can occur", "N/A", "N/A"], ["Fetal anemia/hydrops", "Can be severe", "Usually milder", "No immune fetal disease", "Not classic"], ["Retic", "↑", "↑", "Variable/↑", "↑"], ["Spherocytes", "Can occur", "Can occur", "Not defining", "Characteristic but not exclusive"], ["MCHC", "Not defining", "Not defining", "Not defining", "Often ↑"], ["Major trap", "Late anemia", "DAT ≠ severity", "False-normal acute enzyme assay", "Spherocytes not specific"]]}]}, {"title": "Algorithm 1 — Jaundiced Newborn", "h1": "Part IX — Exam Algorithms", "blocks": [{"t": "list", "ordered": true, "items": ["Determine GA and exact age in hours.", "Measure bilirubin; obtain TSB whenever a treatment decision is required.", "Assess neurotoxicity risk factors and trajectory.", "First-24-hour jaundice / rapid rise / anemia → hemolysis/sepsis evaluation.", "Compare TSB with correct phototherapy threshold.", "Below threshold → feeding optimization + follow-up based on distance from threshold and context.", "At/above phototherapy threshold → intensive phototherapy + cause evaluation.", "At/above escalation threshold → emergency escalation pathway.", "At/above exchange threshold OR intermediate/advanced ABE → urgent exchange."]}]}, {"title": "Algorithm 2 — Phototherapy Not Working", "h1": "", "blocks": [{"t": "list", "ordered": true, "items": ["Confirm current TSB.", "Measure/check light irradiance, wavelength, distance and surface exposure.", "Look for ongoing hemolysis.", "Confirm correct GA/risk curve.", "Determine whether escalation threshold is reached.", "Examine for ABE—neurologic signs can override a reassuring bilirubin trend."]}]}]}, {"id": "connections", "title": "Cross-Day Connections", "group": "Quick Reference", "kind": "notes", "sections": [{"title": "", "blocks": [{"t": "table", "head": ["<strong>Day 6 topic</strong>", "<strong>Cross-reference</strong>", "<strong>Learning link</strong>"], "rows": [["G6PD deficiency", "Day 48 — Hemolytic anemia/G6PD", "Connect neonatal jaundice to enzymopathy, triggers, repeat testing and counseling."], ["Hereditary spherocytosis", "Day 48 — Hemolytic anemia", "Connect DAT-negative neonatal jaundice to membrane disease and later anemia/splenomegaly."], ["Sepsis", "Day 3 — Neonatal sepsis/meningitis", "Sepsis is both a cause/context for jaundice and an AAP neurotoxicity risk factor."], ["Prematurity / feeding / albumin", "Day 4 — Prematurity/ELBW", "Preterm physiology changes feeding, albumin, vulnerability and bilirubin management."], ["Cholestasis / pale stool", "Day 44 — Neonatal cholestasis", "Direct hyperbilirubinemia follows a different diagnostic pathway; phototherapy is not definitive therapy."], ["Critical illness / acid-base", "Day 5 — Ventilation + ABG", "Instability and acid-base disturbance can coexist with severe jaundice and alter risk context."], ["UGT1A1 disorders", "Day 17/18 — Genetics + IEM", "Crigler-Najjar/Gilbert link bilirubin phenotype with genetic/metabolic reasoning."], ["Exchange complications", "Day 49/60 — Coagulation + critical care", "Connect thrombocytopenia, glucose/electrolytes and hemodynamic/transfusion complications."]]}]}]}, {"id": "cases", "title": "Clinical Cases", "group": "Practice", "kind": "cases", "sections": [{"title": "Case 1 — First-day jaundice: do not call it physiologic", "blocks": [{"t": "p", "html": "Patient: Male, 38+4 weeks, BW 3.15 kg, age 12 h; vaginal delivery with scalp bruising.<br>Vitals/clinical: T 36.8 C, HR 146/min, RR 44/min, SpO2 98% RA; feeding fair; jaundice to upper chest.<br>Labs: TSB 8.9 mg/dL at 12 h; Hb 16.2 g/dL; retic 4%; mother O+, infant B+; DAT pending.<br>Specific question: Is this physiologic jaundice, and what is the next step?<br>Structured reasoning: First-24-hour jaundice is pathologic until evaluated. Determine the hour-specific threshold, repeat/track TSB, assess rate of rise, bruising, hemolysis and sepsis risk. A modest absolute TSB does not make first-day jaundice physiologic.<br>Trap identified: Reassurance based only on the absolute bilirubin value."}, {"t": "callout", "label": "WHAT WOULD YOU DO NEXT?", "title": "", "html": ["First-day jaundice is pathologic until evaluated; obtain TSB and assess hemolysis/sepsis and threshold."], "fill": "7F6000"}]}, {"title": "Case 2 — 36-week infant and the wrong AAP curve", "blocks": [{"t": "p", "html": "Patient: Female, 36+3 weeks, BW 2.45 kg, age 40 h; clinically well.<br>Vitals/clinical: T 36.7 C, HR 138/min, RR 46/min; feeding 8 times/day; no instability.<br>Labs: TSB 12.8 mg/dL; albumin 3.5 g/dL; DAT negative; Hb 16 g/dL; retic 3%.<br>Specific question: Should the additional-neurotoxicity-risk curve be used solely because GA is &lt;38 weeks?<br>Structured reasoning: No. Gestational age is already incorporated into the 35–37 6/7-week curve. Use the additional-risk curve only when another neurotoxicity risk factor exists.<br>Trap identified: Double-counting gestational age and overtreating."}, {"t": "callout", "label": "WHAT WOULD YOU DO NEXT?", "title": "", "html": ["Do not double-count GA. Use the GA-specific curve without an additional-risk curve."], "fill": "7F6000"}]}, {"title": "Case 3 — Rate of rise reveals hemolysis", "blocks": [{"t": "p", "html": "Patient: Male, 39 weeks, BW 3.3 kg; jaundice noted early.<br>Vitals/clinical: At 22 h HR 152/min, RR 48/min, perfusion normal, mild pallor.<br>Labs: TSB 8.0 mg/dL at 10 h -&gt; 12.0 mg/dL at 22 h; Hb 13.0 g/dL; retic 9%; DAT positive.<br>Specific question: What do the bilirubin kinetics suggest?<br>Structured reasoning: Rise = 4/12 = 0.33 mg/dL/h. In the first 24 h this exceeds the AAP hemolysis signal (&gt;=0.3 mg/dL/h). Complete hemolysis evaluation and assess treatment threshold without delaying therapy.<br>Trap identified: Looking only at the latest TSB and ignoring trajectory."}, {"t": "callout", "label": "WHAT WOULD YOU DO NEXT?", "title": "", "html": ["Rise ≈0.33 mg/dL/h in first 24 h → hemolysis signal; investigate while treating by threshold."], "fill": "7F6000"}]}, {"title": "Case 4 — ABO HDFN: DAT is etiologic, not a treatment threshold", "blocks": [{"t": "p", "html": "Patient: Female, 37+5 weeks, 30 h old; mother O+, infant A+.<br>Vitals/clinical: HR 148/min, RR 42/min, no distress; jaundice to thighs.<br>Labs: TSB 14.6 mg/dL; Hb 13.1 g/dL; retic 9%; DAT positive; smear with polychromasia and occasional spherocytes.<br>Specific question: Does positive DAT itself mandate IVIG or exchange?<br>Structured reasoning: DAT supports isoimmune hemolysis, but management depends on GA, age-hours, TSB, neurotoxicity risks, trajectory, phototherapy response and neurologic status. IVIG is not automatic.<br>Trap identified: Treating a laboratory marker instead of the infant's severity."}, {"t": "callout", "label": "WHAT WOULD YOU DO NEXT?", "title": "", "html": ["ABO HDFN is plausible; treat according to bilirubin trajectory, not DAT alone."], "fill": "7F6000"}]}, {"title": "Case 5 — G6PD hidden by a 'normal' acute assay", "blocks": [{"t": "p", "html": "Patient: Male, 40 weeks, 48 h old; ancestry with high G6PD prevalence; no known oxidant exposure.<br>Vitals/clinical: HR 154/min, RR 50/min; marked jaundice, no shock.<br>Labs: TSB 20.5 mg/dL; DAT negative; Hb 14.4 g/dL; retic 12%; G6PD reported normal during acute event.<br>Specific question: Can G6PD deficiency be excluded?<br>Structured reasoning: No. Preferential loss of older deficient RBCs plus reticulocytosis can yield falsely reassuring activity. Treat bilirubin severity now and repeat G6PD testing later if suspicion remains.<br>Trap identified: Treating one acute normal assay as definitive."}, {"t": "callout", "label": "WHAT WOULD YOU DO NEXT?", "title": "", "html": ["G6PD remains possible; repeat later if suspicion persists."], "fill": "7F6000"}]}, {"title": "Case 6 — Hereditary spherocytosis versus immune spherocytosis", "blocks": [{"t": "p", "html": "Patient: Male, 38 weeks, 36 h old; father had splenectomy for chronic anemia at 19 years.<br>Vitals/clinical: HR 150/min, RR 44/min; mild pallor, no hepatosplenomegaly yet.<br>Labs: TSB 17.2 mg/dL; DAT negative; Hb 11.8 g/dL; retic 10%; MCHC 37.2 g/dL; many spherocytes.<br>Specific question: What diagnosis is most likely?<br>Structured reasoning: DAT-negative hemolysis + high MCHC + spherocytes + family history strongly suggests HS. Manage bilirubin urgently, then confirm with hematology-directed testing such as EMA binding per local practice.<br>Trap identified: Assuming spherocytes alone prove ABO disease or, conversely, prove HS without context."}, {"t": "callout", "label": "WHAT WOULD YOU DO NEXT?", "title": "", "html": ["HS is strongly suggested."], "fill": "7F6000"}]}, {"title": "Case 7 — 'Double phototherapy' that is not intensive", "blocks": [{"t": "p", "html": "Patient: Female, 38+6 weeks, 56 h old, under two light sources for 5 h.<br>Vitals/clinical: HR 142/min, RR 40/min, temperature stable; neuro exam normal.<br>Labs/device: TSB 18.2 -&gt; 19.4 mg/dL; irradiance only 14 µW/cm2/nm; much of trunk covered; DAT negative.<br>Specific question: Why is treatment failing and what should be corrected first?<br>Structured reasoning: Device count does not equal dose. Optimize blue-green wavelength, measured intensive irradiance, distance and exposed surface; simultaneously assess ongoing production and escalation threshold.<br>Trap identified: Equating 'double phototherapy' with effective intensive phototherapy."}, {"t": "callout", "label": "WHAT WOULD YOU DO NEXT?", "title": "", "html": ["The delivered dose is inadequate; correct it and assess hemolysis/escalation."], "fill": "7F6000"}]}, {"title": "Case 8 — Escalation before the exchange line", "blocks": [{"t": "p", "html": "Patient: Male, 37 weeks, 52 h old, DAT-positive isoimmune HDFN on verified intensive phototherapy.<br>Vitals/clinical: HR 158/min, RR 48/min, BP stable; alert but feeding poorly.<br>Labs: TSB now 1.4 mg/dL below exchange threshold; Hb 10.6 g/dL; retic 11%; albumin 2.9 g/dL.<br>Specific question: What is the next management bundle?<br>Structured reasoning: The infant is above the AAP escalation threshold (2 mg/dL below exchange). Intensive lights + IV hydration + NICU care + STAT CBC/albumin/chemistries/type-cross + q2h TSB + exchange readiness. IVIG may be considered only in the appropriate DAT-positive isoimmune setting and cannot delay exchange.<br>Trap identified: Waiting for the numeric exchange line."}, {"t": "callout", "label": "WHAT WOULD YOU DO NEXT?", "title": "", "html": ["Already in escalation zone: NICU, IV hydration, type/cross, q2h TSB, exchange readiness; consider AAP IVIG."], "fill": "7F6000"}]}, {"title": "Case 9 — ABE overrides a falling TSB", "blocks": [{"t": "p", "html": "Patient: Female, 38 weeks, 72 h old; severe hyperbilirubinemia under intensive phototherapy.<br>Vitals/clinical: HR 166/min, RR 38/min with intermittent apnea; high-pitched cry, hypertonia, retrocollis and opisthotonos.<br>Labs: TSB fell from 25.1 to 23.7 mg/dL and is now slightly below exchange line; albumin 3.1 g/dL.<br>Specific question: Is continued phototherapy alone acceptable because TSB is falling?<br>Structured reasoning: No. Intermediate/advanced ABE signs are an urgent indication for exchange. Neurotoxicity is already occurring; a favorable TSB trend does not neutralize the emergency.<br>Trap identified: Letting a falling laboratory number override dangerous neurologic signs."}, {"t": "callout", "label": "WHAT WOULD YOU DO NEXT?", "title": "", "html": ["Intermediate ABE → urgent exchange despite improving number."], "fill": "7F6000"}]}, {"title": "Case 10 — Dynamic decision during exchange preparation", "blocks": [{"t": "p", "html": "Patient: Male, 39+2 weeks, 60 h old; admitted with TSB at exchange threshold; no neurologic signs.<br>Vitals/clinical: HR 144/min, RR 42/min, BP normal; tone and feeding improve during treatment.<br>Labs: Intensive phototherapy lowers TSB 0.6 mg/dL below exchange threshold before procedure; repeat neuro exam remains normal.<br>Specific question: Must exchange proceed because threshold was crossed earlier?<br>Structured reasoning: AAP allows deferral if TSB falls below exchange threshold and no intermediate/advanced ABE signs are present, provided intensive phototherapy and q2h TSB continue until below escalation threshold with exchange readiness maintained.<br>Trap identified: Treating exchange as permanently fixed rather than dynamic under close monitoring."}, {"t": "callout", "label": "WHAT WOULD YOU DO NEXT?", "title": "", "html": ["AAP allows deferral under close monitoring: intensive phototherapy + q2h TSB until below escalation threshold."], "fill": "7F6000"}]}]}, {"id": "data", "title": "Data Interpretation", "group": "Practice", "kind": "data", "sections": [{"title": "", "blocks": [{"t": "table", "head": ["<strong>Station</strong>", "<strong>Data</strong>", "<strong>Interpretation</strong>"], "rows": [["1 — Bilirubin kinetics", "TSB 6.5 at 8 h -&gt; 10.4 at 20 h; Hb 12.8; retic 10%", "Rise = 0.325 mg/dL/h in first 24 h -&gt; hemolysis signal; investigate and assess threshold."], ["2 — Hemolysis phenotype", "DAT−; Hb 11.5; retic 11%; MCHC 37.4; spherocytes; parent splenectomy", "Strongly supports hereditary spherocytosis."], ["3 — Phototherapy audit", "LED 465–485 nm; irradiance 13 µW/cm2/nm; infant largely covered; TSB unchanged after 5 h", "Spectrum okay, dose/exposed area inadequate; optimize irradiance and surface area."], ["4 — Neurologic station", "High-pitched cry + hypertonia + retrocollis/opisthotonos; TSB just below exchange line", "Intermediate ABE -&gt; urgent exchange despite reassuring TSB trend."], ["5 — Cholestasis", "TSB 12; direct 6.8; dark urine; pale stools", "Conjugated hyperbilirubinemia -&gt; urgent cholestasis work-up; phototherapy is not definitive therapy."], ["6 — Escalation", "DAT+ HDFN; TSB 1.3 below exchange threshold; albumin 2.7", "Above escalation threshold -&gt; emergency bundle, q2h TSB and exchange readiness."]]}]}]}, {"id": "pearls", "title": "Pearls & Traps", "group": "Practice", "kind": "pearls", "sections": [{"title": "22 Exam Pearls", "blocks": [{"t": "list", "ordered": false, "items": ["First-24-hour jaundice is pathologic until evaluated.", "TSB—not TcB—is definitive for treatment decisions.", "TcB within 3 mg/dL of phototherapy threshold or ≥15 mg/dL needs TSB.", "Do not subtract direct bilirubin from TSB.", "Rate ≥0.3 mg/dL/h in first 24 h or ≥0.2 thereafter suggests hemolysis.", "Albumin &lt;3.0 is a neurotoxicity risk factor.", "Sepsis and recent instability lower safety margin.", "Do not double-count GA in 35–37 6/7 wk infants.", "ABO disease can affect a first pregnancy.", "DAT strength does not reliably grade severity.", "G6PD can be severe without obvious anemia or trigger.", "Acute G6PD assay can be falsely normal.", "Spherocytes are not specific for HS.", "High MCHC + DAT− + family history strongly suggests HS.", "Kell can suppress erythropoiesis.", "“Double” phototherapy is not proof of intensive dose.", "Intensive phototherapy requires measured irradiance and large exposed area.", "Escalation threshold is 2 mg/dL below exchange line.", "Escalation requires q2h TSB.", "IVIG is an option only in the correct isoimmune setting; never delay exchange.", "Intermediate/advanced ABE mandates exchange.", "After significant HDFN, follow for late anemia."]}]}, {"title": "15 Traps", "blocks": [{"t": "list", "ordered": false, "items": ["Using a fixed TSB cutoff without exact postnatal age in hours.", "Calling first-24-hour jaundice physiologic because TSB is 'not very high'.", "Using TcB as the final value for treatment escalation/exchange decisions.", "Subtracting direct bilirubin from TSB before applying AAP thresholds.", "Using the additional-risk curve for every 35–37 6/7-week infant and double-counting GA.", "Ignoring rise &gt;=0.3 mg/dL/h in first 24 h or &gt;=0.2 mg/dL/h thereafter as a hemolysis signal.", "Giving IVIG simply because DAT is positive when escalation criteria are not reached.", "Assuming DAT-negative jaundice excludes hemolysis and missing G6PD deficiency or HS.", "Calling an acute normal G6PD result definitive despite reticulocytosis.", "Calling all spherocytes HS despite a positive DAT/immune-HDFN context.", "Accepting 'double phototherapy' without checking wavelength, irradiance, distance and exposed surface.", "Waiting until the exchange line instead of escalating at 2 mg/dL below it.", "Continuing lights alone when hypertonia, retrocollis/opisthotonos, apnea or seizures appear.", "Treating pale stool + dark urine + high direct bilirubin with stronger lights instead of a cholestasis pathway.", "Stopping phototherapy without considering rebound risk in GA &lt;38 wk, early therapy or hemolysis."]}]}]}, {"id": "quizzes", "title": "Quizzes", "group": "Practice", "kind": "quizzes", "sections": []}, {"id": "revision", "title": "Rapid Revision", "group": "Revise", "kind": "revision", "sections": [{"title": "", "blocks": [{"t": "list", "ordered": false, "items": ["First 24 h jaundice = pathologic until evaluated.", "TSB = definitive treatment-decision value.", "TcB within 3 mg/dL of phototherapy line -&gt; TSB.", "TcB &gt;=15 mg/dL -&gt; TSB.", "Do not subtract direct bilirubin from TSB.", "Rise &gt;=0.3 mg/dL/h in first 24 h -&gt; suspect hemolysis.", "Rise &gt;=0.2 mg/dL/h after 24 h -&gt; suspect hemolysis.", "Risk factors: albumin &lt;3, hemolysis/G6PD, sepsis, recent significant instability.", "35–37 6/7 wk: additional-risk curve only with another risk factor.", "ABO HDFN can occur in first pregnancy.", "DAT supports etiology; DAT alone does not set treatment.", "G6PD can cause severe jaundice with modest anemia.", "Acute G6PD assay may be falsely normal during reticulocytosis.", "DAT− + high MCHC + spherocytes + family history -&gt; HS.", "Kell can suppress erythropoiesis.", "Intensive phototherapy: blue-green ~460–490 nm.", "Intensive irradiance: about &gt;=30 µW/cm2/nm in term infants.", "Maximize exposed surface; 'double lights' is not a dose.", "Effective therapy should lower TSB within ~4–6 h if no brisk hemolysis.", "Phototherapy failure -&gt; audit dose + search ongoing production.", "Escalation = 2 mg/dL below exchange threshold.", "Escalation -&gt; NICU + intensive lights + IV hydration + STAT labs/type-cross + q2h TSB.", "AAP IVIG: 0.5–1 g/kg over 2 h; DAT+ isoimmune disease at/above escalation; benefit uncertain.", "IVIG never delays exchange readiness.", "ABE: hypertonia, high-pitched cry, retrocollis/opisthotonos, apnea/seizures.", "Intermediate/advanced ABE -&gt; urgent exchange.", "Double-volume exchange teaching calculation: 2 × 85 mL/kg = 170 mL/kg.", "Continue intensive phototherapy while exchange is prepared.", "After exchange/HDFN: monitor rebound bilirubin + anemia/platelets/electrolytes.", "Pale stool + dark urine + high direct bilirubin -&gt; cholestasis pathway."]}]}]}, {"id": "recall", "title": "Active Recall", "group": "Revise", "kind": "recall", "sections": [{"title": "", "blocks": [{"t": "list", "ordered": false, "items": ["List all AAP neurotoxicity risk factors.<br>Answer: Albumin &lt;3.0 g/dL; isoimmune hemolytic disease; G6PD deficiency or another hemolytic condition; sepsis; and significant clinical instability in the previous 24 hours. Gestational age is already incorporated into the AAP treatment curves.", "State both hemolytic rates of rise.<br>Answer: TSB rise ≥0.3 mg/dL/hour during the first 24 hours, or ≥0.2 mg/dL/hour after 24 hours, strongly suggests hemolysis.", "When must TcB be confirmed by TSB?<br>Answer: Obtain TSB when TcB is within 3 mg/dL of the phototherapy threshold or when TcB is ≥15 mg/dL. TSB is the definitive value for treatment decisions.", "Why is direct bilirubin not subtracted from TSB?<br>Answer: AAP treatment thresholds are based on total serum bilirubin, not 'indirect bilirubin'. Subtracting the direct fraction would underestimate the value used by the guideline.", "Define escalation threshold.<br>Answer: The AAP escalation-of-care threshold is 2 mg/dL below the exchange-transfusion threshold.", "List immediate escalation actions in order.<br>Answer: 1) Start/continue intensive phototherapy. 2) Begin IV hydration as clinically appropriate. 3) Move to NICU/exchange-capable care. 4) Obtain STAT TSB/direct bilirubin, CBC, albumin, chemistries, type and crossmatch. 5) Measure TSB at least every 2 hours. 6) Prepare for urgent exchange while continuing treatment.", "Give the AAP IVIG dose and exact setting.<br>Answer: IVIG 0.5–1 g/kg over 2 hours may be considered in DAT-positive isoimmune hemolytic disease when TSB reaches or exceeds the escalation-of-care threshold; a repeat dose may be considered after 12 hours. Benefit is uncertain, so exchange readiness must continue.", "How does NICE IVIG guidance differ?<br>Answer: NICE recommends IVIG 500 mg/kg over 4 hours as an adjunct to intensified phototherapy in Rh or ABO hemolytic disease when bilirubin continues to rise &gt;8.5 µmol/L/hour (about 0.5 mg/dL/hour). This differs from the AAP escalation-threshold framework.", "List intermediate and advanced ABE signs.<br>Answer: Intermediate: irritability, hypertonia, high-pitched cry, retrocollis and opisthotonos. Advanced: pronounced arching, recurrent apnea, seizures and coma.", "Give both urgent exchange indications.<br>Answer: Urgent exchange is indicated when TSB is at or above the exchange-transfusion threshold, or when intermediate/advanced acute bilirubin encephalopathy is present regardless of whether the TSB is slightly below the numeric line.", "When can exchange be deferred after preparation starts?<br>Answer: If intensive phototherapy lowers TSB below the exchange threshold and the infant has no intermediate/advanced ABE signs, exchange may be deferred with continued intensive phototherapy, q2h TSB monitoring and full exchange readiness until TSB falls below escalation threshold.", "What makes phototherapy intensive?<br>Answer: Appropriate blue-green spectrum about 460–490 nm, measured irradiance around ≥30 µW/cm²/nm in term infants, correct device distance/configuration, and maximal safely exposed body surface area.", "List five reasons phototherapy may fail.<br>Answer: Inadequate irradiance; excessive distance/wrong device setup; too little exposed skin; ongoing brisk hemolysis or other high bilirubin production; use of the wrong GA/risk threshold. Also consider lab error, conjugated disease, and poor adherence/interruption.", "Differentiate ABO HDFN, G6PD and HS.<br>Answer: ABO HDFN: usually DAT positive, often group O mother with A/B infant, reticulocytosis ± spherocytes. G6PD: DAT negative, severe jaundice may occur with modest anemia, enzyme assay can be falsely normal during acute hemolysis. HS: DAT negative, spherocytes, often high MCHC and family history.", "Why can G6PD testing be falsely normal?<br>Answer: During acute hemolysis, the most enzyme-deficient older RBCs are preferentially destroyed, leaving younger RBCs/reticulocytes with relatively higher G6PD activity and a falsely reassuring result.", "What is unique about Kell HDFN?<br>Answer: Anti-Kell can suppress fetal erythroid progenitors in addition to causing immune RBC destruction, so severe anemia may occur with a relatively lower reticulocyte response and sometimes less dramatic bilirubin production than classic anti-D disease.", "How does suboptimal intake raise bilirubin?<br>Answer: Poor milk transfer causes reduced caloric intake and fewer stools, increasing intestinal deconjugation and enterohepatic reabsorption of bilirubin.", "What signs indicate cholestasis?<br>Answer: Direct/conjugated hyperbilirubinemia, dark urine, pale or acholic stools, hepatomegaly or persistent jaundice. Phototherapy does not treat the underlying cholestatic disorder.", "Name rebound risk factors.<br>Answer: Gestational age &lt;38 weeks, phototherapy started before 48 hours of age, hemolytic disease, and stopping phototherapy when TSB remains close to the treatment threshold.", "What late issue follows significant HDFN?<br>Answer: Late anemia due to ongoing antibody-mediated RBC destruction and/or suppressed erythropoiesis; infants need hemoglobin/reticulocyte follow-up even after bilirubin is controlled.", "State the common 300 µg (1500 IU) anti-D antenatal/postpartum regimen and when postpartum dosing is required.<br>Answer: A common regimen uses 300 µg (1500 IU) Rh(D) immune globulin at about 28 weeks' gestation, with another 300 µg (1500 IU) within 72 hours after delivery if an unsensitized RhD-negative mother delivers an RhD-positive infant. Local product/regional schedules may differ.", "How is extra anti-D dosing determined after a large fetomaternal hemorrhage or sensitizing event?<br>Answer: Quantify fetomaternal hemorrhage using the local blood-bank method (for example Kleihauer-Betke testing or flow cytometry) and give additional Rh(D) immune globulin according to the calculated volume of fetal RBC exposure and product-specific dosing rules.", "Why can anti-Kell HDFN produce severe anemia with a less impressive reticulocyte response?<br>Answer: Anti-Kell targets erythroid precursor cells and suppresses erythropoiesis, so anemia is caused partly by reduced RBC production rather than hemolysis alone; the marrow response may therefore be relatively blunted.", "Calculate a term double-volume exchange using 2 × 85 mL/kg and explain why the final procedural volume must follow the NICU/blood-bank protocol.<br>Answer: 2 × 85 mL/kg = 170 mL/kg. This is a teaching estimate for two blood volumes in a term infant; the final exchange volume, aliquot size and component specification must follow the infant's actual estimated blood volume, gestation, clinical status, NICU protocol and blood-bank preparation.", "After significant HDFN, what two late problems must be followed even after bilirubin is controlled?<br>Answer: Rebound hyperbilirubinemia and late anemia. Depending on severity/exchange therapy, also monitor reticulocyte response, platelets and other post-transfusion issues."]}]}]}, {"id": "notebook", "title": "Error Notebook", "group": "Revise", "kind": "notebook", "sections": []}, {"id": "plan", "title": "Revision Plan", "group": "Revise", "kind": "plan", "sections": [{"title": "Self-Assessment & K/C/R/G/S Error Notebook", "h1": "Self-Assessment & K/C/R/G/S Error Notebook", "blocks": [{"t": "table", "head": ["<strong>Item</strong>", "<strong>Record</strong>"], "rows": [["Score", "____ / 75"], ["Basic/Recall errors", "____"], ["Conceptual errors", "____"], ["Clinical/Application errors", "____"], ["High-Difficulty errors", "____"], ["Integrated errors", "____"], ["Guessed-correct", "____"], ["Guessed-wrong", "____"], ["Top 5 weak areas", "1.__ 2.__ 3.__ 4.__ 5.__"], ["Error codes", "K = Knowledge | C = Concept | R = Reasoning | G = Guessing | S = Careless"], ["Wrong-question numbers by code", "K: ____ | C: ____ | R: ____ | G: ____ | S: ____"], ["Trigger I missed", "Threshold / timing / risk factor / trajectory / neurologic sign / lab pattern: __________________"], ["Why my chosen option was wrong", "____________________________________________________________"], ["Correct rule in one sentence", "____________________________________________________________"], ["48–72 h retest result", "Date: ____  Score: ____ / ____  Remaining error code: ____"]]}]}, {"title": "R1 / R2 / R3 Spaced Revision", "h1": "R1 / R2 / R3 Spaced Revision", "blocks": [{"t": "table", "head": ["<strong>Cycle</strong>", "<strong>When</strong>", "<strong>Task</strong>"], "rows": [["R1", "24 hours", "Rebuild the jaundice algorithm and all MUST-KNOW numbers from memory; redo wrong/guessed MCQs."], ["R2", "7 days", "20-minute closed-book recall + 20 mixed bilirubin/hemolysis questions; retest K/C errors."], ["R3", "21 days", "Recreate phototherapy→escalation→exchange pathway; retest R/G errors and all 10 clinical cases."]]}]}]}, {"id": "references", "title": "References", "group": "More", "kind": "notes", "sections": [{"title": "Current Guideline References", "h1": "Current Guideline References", "blocks": [{"t": "list", "ordered": true, "items": ["American Academy of Pediatrics. Clinical Practice Guideline Revision: Management of Hyperbilirubinemia in the Newborn Infant 35 or More Weeks of Gestation. Pediatrics. 2022;150(3):e2022058859.", "American Academy of Pediatrics. Technical Report: Diagnosis and Management of Hyperbilirubinemia in the Newborn Infant 35 or More Weeks of Gestation. Pediatrics. 2022;150(3):e2022058865.", "American Academy of Pediatrics. Phototherapy to Prevent Severe Neonatal Hyperbilirubinemia in the Newborn Infant 35 or More Weeks of Gestation: Technical Report. Pediatrics. 2024;154(3).", "NICE. Jaundice in newborn babies under 28 days (CG98), current online recommendations accessed for IVIG/exchange comparison."]}, {"t": "callout", "label": "EDUCATIONAL USE", "title": "", "html": ["This document is for postgraduate exam preparation. Bedside care must use the infant’s actual gestational age, exact age in hours, current local bilirubin calculator/chart, neonatal unit protocol and transfusion-medicine policy."], "fill": "1F4E78"}, {"t": "p", "html": "• FDA RhoGAM/MICRhoGAM prescribing information: 300 µg (1500 IU) at 26–28 weeks and within 72 h postpartum after an RhD-positive birth; 50 µg (250 IU) through 12 weeks where available; quantify FMH for additional dosing."}, {"t": "p", "html": "• NICE TA156 / current UK anti-D practice: product-dependent routine antenatal prophylaxis (including single 1500 IU at 28–30 weeks or licensed two-dose regimens); postpartum prophylaxis remains required when indicated."}, {"t": "p", "html": "• BSH 2026 fetomaternal-haemorrhage guidance: FMH estimation is used to ensure sufficient additional anti-D after significant fetal-RBC exposure."}]}, {"title": "Document QA", "h1": "Document QA", "blocks": [{"t": "table", "head": ["<strong>Check</strong>", "<strong>Result</strong>"], "rows": [["Total MCQs", "75"], ["Basic/Recall", "7"], ["Conceptual", "13"], ["Clinical/Application", "27"], ["High-Difficulty", "20"], ["Integrated/Rank-Differentiating", "8"], ["Correct-answer distribution", "A=19 | B=19 | C=19 | D=18"], ["Wrong-option explanations", "All distractors rewritten with option-specific factual reasoning"], ["Pearls / question relevance", "75 unique pearls + 75 unique “Why This Question Matters” blocks"], ["Algorithm numbering", "Restarted at Algorithm 1"], ["Anti-D prevention", "Explicit dose/regimen and FMH top-up notes added"], ["Active recall / error notebook", "Expanded to 25 prompts + error-repair fields"]]}, {"t": "p", "html": "Answer-key indices, option counts and requested difficulty distribution were validated programmatically before save."}]}]}], "quizSets": [{"k": 1, "from": 1, "to": 15, "n": 15}, {"k": 2, "from": 16, "to": 30, "n": 15}, {"k": 3, "from": 31, "to": 45, "n": 15}, {"k": 4, "from": 46, "to": 60, "n": 15}, {"k": 5, "from": 61, "to": 75, "n": 15}], "mcqCount": 75};
